import 'dart:convert';
import 'dart:io';

import 'package:mcp_dart/mcp_dart.dart';

import 'package:gitvault/mcp/mcp_paths_io.dart';

Future<void> main(List<String> arguments) async {
  silenceMcpLogs();
  final profileId = _profileArgument(arguments);
  if (profileId == null) {
    stderr.writeln(
      'GitVault MCP: use --profile <id> from the configuration generated by GitVault Desktop.',
    );
    exitCode = 64;
    return;
  }

  try {
    final discovery = await _readJson(McpLocalPaths.discoveryFile());
    final profile = await _readJson(McpLocalPaths.profileFile(profileId));
    final endpoint = Uri.tryParse(discovery['endpoint'] as String? ?? '');
    final token = profile['token'] as String?;
    final storedClientId = profile['client_id'] as String?;
    if (endpoint == null ||
        endpoint.host != '127.0.0.1' ||
        token == null ||
        token.isEmpty ||
        storedClientId != profileId) {
      throw const FormatException('Invalid GitVault MCP profile.');
    }

    final remoteClient = McpClient(
      const Implementation(
        name: 'gitvault-stdio-bridge',
        version: '1.0.0',
      ),
      options: const McpClientOptions(protocol: McpProtocol.stable),
    );
    final remoteTransport = StreamableHttpClientTransport(
      endpoint,
      opts: StreamableHttpClientTransportOptions(
        requestInit: {
          'headers': {'Authorization': 'Bearer $token'},
        },
      ),
    );
    remoteClient.onerror = (error) {
      stderr.writeln('GitVault MCP connection error: $error');
    };
    await remoteClient.connect(remoteTransport);

    final localServer = McpServer(
      const Implementation(
        name: 'gitvault-notes',
        version: '1.0.0',
      ),
      options: const McpServerOptions(
        protocol: McpProtocol.stable,
        capabilities: ServerCapabilities(
          tools: ServerCapabilitiesTools(),
          resources: ServerCapabilitiesResources(),
        ),
      ),
    );

    await _proxyTools(remoteClient, localServer);
    await _proxyResources(remoteClient, localServer);
    await localServer.connect(StdioServerTransport());
  } on FileSystemException {
    stderr.writeln(
      'GitVault MCP: GitVault Desktop is not running or this AI app profile no longer exists.',
    );
    exitCode = 69;
  } on SocketException {
    stderr.writeln(
      'GitVault MCP: could not connect to GitVault Desktop. Open the desktop app and unlock the vault.',
    );
    exitCode = 69;
  } catch (error) {
    stderr.writeln('GitVault MCP: $error');
    exitCode = 70;
  }
}

Future<void> _proxyTools(
  McpClient remote,
  McpServer local,
) async {
  final result = await remote.listTools();
  for (final tool in result.tools) {
    final inputSchema = tool.inputSchema;
    if (inputSchema is! JsonObject) continue;
    final outputSchema = tool.outputSchema;
    local.registerTool(
      tool.name,
      title: tool.title,
      description: tool.description,
      inputSchema: inputSchema,
      outputSchema: outputSchema is JsonObject ? outputSchema : null,
      annotations: tool.annotations,
      callback: (arguments, extra) {
        return remote.callTool(
          CallToolRequest(
            name: tool.name,
            arguments: arguments,
          ),
          options: const RequestOptions(
            timeout: Duration(seconds: 75),
          ),
        );
      },
    );
  }
}

Future<void> _proxyResources(
  McpClient remote,
  McpServer local,
) async {
  try {
    final result = await remote.listResourceTemplates();
    for (final template in result.resourceTemplates) {
      local.registerResourceTemplate(
        template.name,
        ResourceTemplateRegistration(
          template.uriTemplate,
          listCallback: null,
        ),
        (
          description: template.description,
          mimeType: template.mimeType,
        ),
        (uri, variables, extra) {
          return remote.readResource(
            ReadResourceRequest(uri: uri.toString()),
            const RequestOptions(timeout: Duration(seconds: 30)),
          );
        },
      );
    }
  } catch (error) {
    stderr.writeln('GitVault MCP: note resources unavailable: $error');
  }
}

String? _profileArgument(List<String> arguments) {
  final index = arguments.indexOf('--profile');
  if (index < 0 || index + 1 >= arguments.length) return null;
  final value = arguments[index + 1].trim();
  if (!RegExp(r'^[a-zA-Z0-9-]{1,100}$').hasMatch(value)) return null;
  return value;
}

Future<Map<String, dynamic>> _readJson(File file) async {
  final value = jsonDecode(await file.readAsString());
  if (value is! Map<String, dynamic>) {
    throw const FormatException('Expected a JSON object.');
  }
  return value;
}
